#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nWidth;  COLORREF  lg;// Цвет края  COLORREF  fn;// Цвет центра  COLORREF  dk;// Цвет края  HRGN m_hRgn;  } Queue_PipeH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция удаленияvoid ClearPipeH(SQueue& q,void* s)  {  Queue_PipeH* p = (Queue_PipeH*)s;  ::DeleteObject( p->m_hRgn );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPipeH(DefinePaint)  {  QueueP(Queue_PipeH);  if ( q.curShift.x || q.curShift.y )  ::OffsetRgn( p->m_hRgn, -q.curShift.x, -q.curShift.y );  //  if ( p->fn == p->dk )    {    HBRUSH hBrush = ::CreateSolidBrush(p->fn);    if ( hBrush )      {      ::FillRgn( hDC, p->m_hRgn, hBrush );      ::DeleteObject( hBrush );      }    }  else  if ( p->lg == p->dk )    {    RGBTRIPLE rgb[2];//0-центр,1-край    SetT( rgb[0], p->fn );//0-центр    SetT( rgb[1], p->dk );//1-край    int m = p->nWidth/2;    ::SelectClipRgn( hDC, p->m_hRgn );    RECT rect = p->mRect;    ::InflateRect( &rect, m, 0 );    for ( int n = 0; n <= m; n++ )      {      COLORREF color = Col(rgb[1],rgb[0],(int)n,m);      CMyBrush brs( hDC, color );      brs.Rect(rect);      ::InflateRect( &rect, 0, -1 );      }    ::SelectClipRgn( hDC, NULL );    }  else    {    }  //  if ( q.curShift.x || q.curShift.y )  ::OffsetRgn( p->m_hRgn,  q.curShift.x,  q.curShift.y );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPipeH(DefineTegs)  {  AddQueueEx(Queue_PipeH);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPipeH;  p->clear = &ClearPipeH;  //  int nWidth = 5;  EDirect eFrom = dirFree, eTo = dirFree;  {  POINT pt;  int   x1;  //  STegObj obj[] =    {    { 'I', "w"    , &nWidth },    { 'I', "width", &nWidth },    { 'P', "pt"   , &pt     },    { 'I', "x"    , &pt.x   },    { 'I', "x0"   , &pt.x   },    { 'I', "y"    , &pt.y   },    { 'I', "y0"   , &pt.y   },    { 'I', "x1"   , &x1     },    { 'I', "z"    , &x1     },    { 'N', "from" , &eFrom  },    { 'N', "to"   , &eTo    },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->mRect.top = pt.y-nWidth/2;  p->mRect.bottom = p->mRect.top+p->nWidth;  bool bLeft = ( pt.x > x1 );  if ( bLeft )    {    p->mRect.left  = x1;    p->mRect.right = pt.x;    EDirect eTemp = eTo;    eTo   = eFrom;    eFrom = eTemp;    }  else    {    p->mRect.left  = pt.x;    p->mRect.right = x1;    }  }  //  p->nWidth = nWidth;  p->lg = def.lgPipe;// Цвет края  p->fn = def.fnPipe;// Цвет центра  p->dk = def.dkPipe;// Цвет края  //  // Регион вывода трубки  int m = p->nWidth/2;  POINT pt[6] = {{p->mRect.left,p->mRect.top},{p->mRect.right,p->mRect.top},{p->mRect.right,p->mRect.top+m},                 {p->mRect.right,p->mRect.bottom},{p->mRect.left,p->mRect.bottom},{p->mRect.left,p->mRect.top+m}};  //  if ( eFrom != dirFree || eTo != dirFree )    {    if ( eFrom != dirFree )    switch ( eFrom )      {      case dirUp   : pt[0].x += m;pt[4].x = pt[0].x-p->nWidth;break;      case dirDown : pt[0].x -= m;pt[4].x = pt[0].x+p->nWidth;break;      case dirInner: pt[0].x += m;pt[4].x += m;break;      }    if ( eTo != dirFree )    switch ( eTo )      {      case dirUp   : pt[1].x -= m;pt[3].x = pt[1].x+p->nWidth;break;      case dirDown : pt[1].x += m;pt[3].x = pt[1].x-p->nWidth;break;      case dirInner: pt[1].x -= m;pt[3].x -= m;break;      }    }  //  p->m_hRgn = ::CreatePolygonRgn( pt, 6, WINDING );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~